/** Look up an edge fixture by slug (throws if missing). */
export function edgeKey(slug: string): EdgeKey {
  const key = Object.values(EDGE_KEYS).find((k) => k.slug === slug);
  if (!key) throw new Error(`No edge key with slug "${slug}"`);
  return key;
}
